import {run,THREE,box,sphere,floor,makeHero,poseHero} from './lib/core.js';import {VoxelWorld} from './rules.js';
run({title:'Voxel Trails',genre:'Creative / voxel exploration',accent:'#b3e590',background:0xa6c7d8,description:'A small world you can reshape. Mine, build, explore and find five hidden crystals. Save your island locally and return to it later.',controls:[['W A S D','Move'],['Drag mouse','Look around'],['Space','Jump'],['Click / right-click','Mine / place'],['1–5 / Tab','Choose block'],['K / C / R','Save / view / respawn']],touch:[['KeyA','←'],['KeyD','→'],['KeyW','Forward'],['KeyS','Back'],['Space','Jump'],['KeyE','Mine'],['KeyQ','Place'],['Tab','Block'],['KeyK','Save'],['KeyC','View']],options:[{id:'mode',label:'Mode',values:[['creative','Creative · unlimited blocks'],['explore','Explore · collect to build']]},{id:'world',label:'Island',values:[['new','Start a fresh island'],['saved','Continue saved island']]}],buildIntro:'An original small voxel sandbox: one editable island, a peaceful exploration goal and local world persistence.',build:[['Voxel character in Blender','Designed a Steve fan model and pickaxe, then exported the separate coloured meshes as a GLB.'],['Editable world representation','Stored blocks in a coordinate map and drew them with instanced meshes. Raycasting maps a hit back to a block for mining and face-adjacent placement.'],['Exploration controller','Implemented yaw-based movement, gravity, jumping and voxel collision. Mouse/touch dragging turns the camera without requiring pointer lock.'],['Persistence and objectives','Five crystals encourage exploration. Inventory mode consumes placed blocks; creative mode is unlimited. Validated JSON saves stay in this browser.']]},(ctx,model)=>{const {scene,camera,stage}=ctx;floor(scene,200,0x517f94).position.y=-1.4;const hero=makeHero(model,scene,.65);let sim=new VoxelWorld(),yaw=.6,pitch=-.25,third=false,drag=null,meshes=[],target=null,lastEdits=-1,complete=false;const geometry=new THREE.BoxGeometry(1,1,1),colors=[0,0x71a659,0x8296a1,0xa97a4a,0xa5def0,0xd58b67,0x4c8b56],materials=colors.map(c=>new THREE.MeshStandardMaterial({color:c,roughness:.9})),ray=new THREE.Raycaster(),matrix=new THREE.Matrix4();materials[4].transparent=true;materials[4].opacity=.6;materials[4].depthWrite=false;const crystals=sim.crystals.map(([x,z])=>{const o=new THREE.Mesh(new THREE.OctahedronGeometry(.35),new THREE.MeshStandardMaterial({color:0x8ae9ec,emissive:0x368c9a,emissiveIntensity:.6}));scene.add(o);return o});const outline=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(1.02,1.02,1.02)),new THREE.LineBasicMaterial({color:0xfff5c8}));scene.add(outline);document.querySelector('#crosshair').style.display='block';
function rebuild(){for(const m of meshes){scene.remove(m);m.dispose()}meshes=[];for(let type=1;type<=6;type++){const cells=[...sim.blocks].filter(([,t])=>t===type).map(([k])=>k.split(',').map(Number));if(!cells.length)continue;const m=new THREE.InstancedMesh(geometry,materials[type],cells.length);cells.forEach(([x,y,z],i)=>{matrix.makeTranslation(x,y,z);m.setMatrixAt(i,matrix)});m.userData.cells=cells;m.receiveShadow=true;m.castShadow=true;m.computeBoundingSphere();scene.add(m);meshes.push(m)}lastEdits=sim.edits}
function aim(){ray.setFromCamera(new THREE.Vector2(0,0),camera);const hit=ray.intersectObjects(meshes,false)[0];if(hit&&hit.distance<8){const cell=hit.object.userData.cells[hit.instanceId];target={cell,normal:hit.face.normal};outline.position.set(...cell);outline.visible=true}else{target=null;outline.visible=false}}
function edit(place){if(!target)return;const [x,y,z]=target.cell,n=target.normal;if(sim.edit(x+(place?n.x:0),y+(place?n.y:0),z+(place?n.z:0),place)){rebuild();ctx.tone(place?300:220,.05)}}
stage.addEventListener('pointerdown',e=>{if(!ctx.playing||e.button!==0)return;drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:0};stage.setPointerCapture(e.pointerId)});stage.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.moved+=Math.abs(dx)+Math.abs(dy);yaw-=dx*.005;pitch=Math.max(-1.35,Math.min(1.1,pitch-dy*.005));drag.x=e.clientX;drag.y=e.clientY});stage.addEventListener('pointerup',e=>{if(drag&&drag.moved<6&&ctx.playing)edit(false);drag=null});stage.addEventListener('pointercancel',()=>drag=null);stage.addEventListener('contextmenu',e=>{e.preventDefault();if(ctx.playing)edit(true)});
return {reset(o){sim=new VoxelWorld(o);yaw=.6;pitch=-.25;third=false;complete=false;if(o.world==='saved'){let text=null;try{text=localStorage.getItem('voxel-trails-world')}catch{}ctx.announce(text&&sim.load(text)?'Saved island restored.':'No valid saved island yet. A fresh one is ready.')}else ctx.announce('Find five crystals · reshape your island');rebuild()},update(dt){sim.update(dt,ctx.keys,ctx.pressed,yaw);if(ctx.pressed.has('KeyC'))third=!third;if(ctx.pressed.has('KeyE'))edit(false);if(ctx.pressed.has('KeyQ'))edit(true);if(ctx.pressed.has('KeyK')){try{localStorage.setItem('voxel-trails-world',sim.save());ctx.announce('Island saved in this browser.')}catch{ctx.announce('Browser storage is unavailable. Keep exploring this visit.')}}if(sim.edits!==lastEdits)rebuild();const p=sim.player,dir=new THREE.Vector3(-Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch));camera.position.set(p.x,p.y+1.55,p.z);if(third)camera.position.addScaledVector(dir,-5);camera.lookAt(new THREE.Vector3(p.x,p.y+1.55,p.z).add(dir));hero.visible=third;hero.position.set(p.x,p.y,p.z);hero.rotation.y=yaw+Math.PI;poseHero(hero,ctx.time,ctx.keys.has('KeyW')||ctx.keys.has('KeyA')||ctx.keys.has('KeyS')||ctx.keys.has('KeyD')?1:0);crystals.forEach((o,i)=>{const [x,z]=sim.crystals[i];o.visible=!sim.collected.includes(i);o.position.set(x,sim.top(x,z)+1.3+Math.sin(ctx.time*2+i)*.15,z);o.rotation.y+=dt});aim();if(sim.completed&&!complete){complete=true;ctx.announce('All five crystals found! Your island is still yours to build.');ctx.tone(660,.4)}const labels=['','Grass','Stone','Wood','Glass','Clay'];ctx.hud(`<div><strong>${sim.collected.length} / 5 CRYSTALS</strong><small>${sim.completed?'EXPLORATION COMPLETE · KEEP BUILDING':'EXPLORE THE ISLAND'} · ${sim.edits} EDITS</small></div><div><strong>${sim.selected} · ${labels[sim.selected]}</strong><small>${sim.mode==='creative'?'UNLIMITED BLOCKS':'INVENTORY '+sim.inventory[sim.selected]} · ${third?'THIRD PERSON':'FIRST PERSON'}</small><small>1 Grass · 2 Stone · 3 Wood · 4 Glass · 5 Clay</small></div>`)},snapshot(){return {blocks:sim.blocks.size,edits:sim.edits,collected:sim.collected.length,player:sim.player,completed:sim.completed}}};});
